"% Closed-loop pitch-axis tracking simulation
% Define system matrices
A_cl = [-0.6, 1.0, 0.1; -4.4, -1.6, 0.2; 1.0, 0.5, -4.0];
B_cl = [0.0; 1.0; 0.5];
C_cl = [1.0, 0.0, 0.0];

% Simulation parameters
dt = 0.01;
T = 30;
t_steps = 0:dt:T;
N_steps = length(t_steps);

% Exact zero-order-hold discretization
I_mat = eye(size(A_cl));
Ad = expm(A_cl * dt);
Bd = A_cl \ ((Ad - I_mat) * B_cl);

% Initialize state vector x[0] = 0
x = zeros(3, N_steps);
u = 1; % Unit step input

% Time-stepping simulation
for k = 1:(N_steps-1)
    x(:, k+1) = Ad * x(:, k) + Bd * u;
end

% Output response y(t)
y = C_cl * x;
y = y(:); % Ensure column vector

% Compute DC value y_inf
y_inf = -C_cl * (A_cl \ B_cl);

% --- Rise Time (10% - 90%) ---
thr_low = 0.10 * y_inf;
thr_high = 0.90 * y_inf;

% Find first indices exceeding thresholds
idx_low = find(y >= thr_low, 1);
idx_high = find(y >= thr_high, 1);

% Linear interpolation for time
t_low = 0;
if ~isempty(idx_low) && idx_low > 1
    k_l = idx_low - 1;
    t_k = t_steps(k_l);
    y_k = y(k_l);
    y_k1 = y(idx_low);
    if y_k1 ~= y_k
        t_low = t_k + (thr_low - y_k) * dt / (y_k1 - y_k);
    else
        t_low = t_steps(idx_low);
    end
end

t_high = 0;
if ~isempty(idx_high) && idx_high > 1
    k_h = idx_high - 1;
    t_k = t_steps(k_h);
    y_k = y(k_h);
    y_k1 = y(idx_high);
    if y_k1 ~= y_k
        t_high = t_k + (thr_high - y_k) * dt / (y_k1 - y_k);
    else
        t_high = t_steps(idx_high);
    end
end

rise_time_s = t_high - t_low;

% --- Percent Overshoot ---
max_y = max(y);
overshoot_pct = (max_y - y_inf) / abs(y_inf) * 100;

% --- Settling Time (2%) ---
tol = 0.02 * abs(y_inf);
% Find indices where error exceeds tolerance
err_indices = find(abs(y - y_inf) > tol);

settling_time_s = 0;
if ~isempty(err_indices)
    % Time of the LAST grid sample where condition is met
    settling_time_s = t_steps(err_indices(end));
end

% --- Save Results ---
result = struct();
result.rise_time_s = rise_time_s;
result.overshoot_pct = overshoot_pct;
result.settling_time_s = settling_time_s;

fid = fopen('result.json', 'w');
fprintf(fid, '%s', jsonencode(result));
fclose(fid);"
